#include <stdio.h>

int main(void) {
    int L, C;
    if (scanf("%d %d", &L, &C) != 2) return 0;

    char grid[100][101];
    int sr = -1, sc = -1;

    for (int r = 0; r < L; r++) {
        scanf("%100s", grid[r]);
        for (int c = 0; c < C; c++) {
            if (grid[r][c] == 'o') {
                sr = r;
                sc = c;
            }
        }
    }

    const int dr[4] = {-1, 0, 1, 0};
    const int dc[4] = {0, 1, 0, -1};

    int pr = -1, pc = -1;
    int r = sr, c = sc;

    while (1) {
        int nr = -1, nc = -1;

        for (int d = 0; d < 4; d++) {
            int rr = r + dr[d];
            int cc = c + dc[d];

            if (rr < 0 || rr >= L || cc < 0 || cc >= C) continue;
            if (grid[rr][cc] != 'H') continue;
            if (rr == pr && cc == pc) continue;

            nr = rr;
            nc = cc;
            break;
        }

        if (nr == -1) break;

        pr = r;
        pc = c;
        r = nr;
        c = nc;
    }

    printf("%d %d\n", r + 1, c + 1);
    return 0;
}
